# A deployed agent that Backstage also describes: the pin lets Backstage add its system (never an
# endpoint: a unit deploys it); the description below wins over the Backstage one.
name: ai-coe-mortgage-specialist
kind: a2a
description: A2A mortgage underwriting specialist on Agent Runtime.
owner_team: ai-coe
deploy: { unit: agents/ai-coe-mortgage-specialist }
serving: { token: access, probe: a2a }
backstage: { source: backstage, ref: Component:default/ai-coe-mortgage-specialist }
callers:
  cx-mortgage-orchestrator: { cost_centers: [cc-cx-br] }
  test-vm: {}

{
  "server": {
    "name": "corporate-email",
    "description": "Corporate email system for sending and managing emails."
  },
  "tools": [
    {
      "name": "send_email",
      "description": "Send an email through the corporate email system.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "to": {
            "type": "string",
            "description": "Recipient email address."
          },
          "subject": {
            "type": "string",
            "description": "Email subject line."
          },
          "body": {
            "type": "string",
            "description": "Email body content."
          }
        },
        "required": ["to", "subject", "body"]
      },
      "annotations": {
        "title": "Send Email",
        "readOnlyHint": false,
        "destructiveHint": true,
        "idempotentHint": false,
        "openWorldHint": true
      }
    },
    {
      "name": "read_email",
      "description": "Read emails from the corporate inbox. This is a read-only operation.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "email_id": {
            "type": "string",
            "description": "Optional email ID to fetch a specific email. If not provided, returns all emails in the inbox."
          }
        },
        "required": []
      },
      "annotations": {
        "title": "Read Email",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      }
    }
  ]
}

{
  "server": {
    "name": "income-verification",
    "description": "Verify applicant income through third-party income verification service."
  },
  "tools": [
    {
      "name": "verify_applicant",
      "description": "Verify applicant income through third-party income verification service.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "first_name": {
            "type": "string",
            "description": "Applicant's first name."
          },
          "last_name": {
            "type": "string",
            "description": "Applicant's last name."
          }
        },
        "required": ["first_name", "last_name"]
      },
      "annotations": {
        "title": "Verify Applicant",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": true
      }
    }
  ]
}

{
  "server": {
    "name": "legacy-dms",
    "description": "Legacy Document Management System for retrieving applicant documents."
  },
  "tools": [
    {
      "name": "search_documents",
      "description": "Search the document management system for applicant documents. Pass either the applicant's last name or the loan-file borrower ID; the response includes the resolved borrower (ID and applicant first/last names).",
      "inputSchema": {
        "type": "object",
        "properties": {
          "applicant_last_name": {
            "type": "string",
            "description": "Last name of the applicant. Optional when borrower_id is given.",
            "default": ""
          },
          "document_type": {
            "type": "string",
            "description": "Type of document (e.g. 'tax_return', 'pay_stub', 'bank_statement'), or 'all' (default) for every type.",
            "default": "all"
          },
          "years": {
            "type": "integer",
            "description": "Number of years of documents to retrieve (default 2).",
            "default": 2
          },
          "borrower_id": {
            "type": "string",
            "description": "Loan-file borrower ID (e.g. '1001'). Preferred when known.",
            "default": ""
          }
        }
      },
      "annotations": {
        "title": "Search Documents",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      }
    },
    {
      "name": "get_document",
      "description": "Retrieve a full document from the document management system by ID.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "document_id": {
            "type": "string",
            "description": "The unique document identifier (e.g. 'DOC-2024-SM-1040')."
          }
        },
        "required": ["document_id"]
      },
      "annotations": {
        "title": "Get Document",
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": false
      }
    }
  ]
}

